import sympy as sp
import numpy as np


def init_eji_array(energy, energy_vertices):
    sorted_verts = sorted(energy_vertices)
    energies = [energy] + sorted_verts

    symbols = {}
    value_map = {}

    for i in range(5):
        for j in range(5):
            name = f"e_{j}{i}"
            sym = sp.symbols(name)
            symbols[name] = sym
            value_map[sym] = energies[j] - energies[i]

    return symbols, value_map


def integrate_DOS(energy, energy_vertices):
    eps = sorted(energy_vertices)
    e1, e2, e3, e4 = eps
    E = energy

    if E <= e1 or E >= e4:
        return 0.0

    e21 = e2 - e1
    e31 = e3 - e1
    e41 = e4 - e1
    e32 = e3 - e2
    e42 = e4 - e2
    e43 = e4 - e3

    term1 = (E - e1) ** 2 / (e21 * e31 * e41)

    if E <= e2:
        return 3.0 * term1

    term2 = (E - e2) ** 2 / (e21 * e32 * e42)

    if E <= e3:
        return 3.0 * (term1 - term2)

    term3 = (E - e3) ** 2 / (e31 * e32 * e43)

    return 3.0 * (term1 - term2 + term3)

